package cn.binbin.crm;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;
import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class ServiceDeskService {
 public record Target(@NotNull @Pattern(regexp="URGENT|HIGH|NORMAL|LOW") String priority,@Min(1) @Max(43200) int responseMinutes,@Min(1) @Max(43200) int resolutionMinutes){}
 public record SlaInput(@NotBlank @Size(max=100) String name,@NotEmpty @Size(min=4,max=4) List<@NotNull @Valid Target> targets,boolean pauseWaiting,boolean escalate,boolean active,@Min(0) long expectedVersion){}
 public record TicketInput(@NotBlank @Size(max=200) String title,@Size(max=10000) String description,UUID customerId,@NotNull UUID assigneeMemberId,@NotNull @Pattern(regexp="URGENT|HIGH|NORMAL|LOW") String priority,UUID slaPolicyId,@Size(max=100) String requesterName,@Email @Size(max=254) String requesterEmail,@Min(0) long expectedVersion,@Pattern(regexp="[A-Z0-9_]{1,40}") String typeCode){}
 public record Change(@Min(0) long expectedVersion,@NotBlank @Size(max=1000) String reason){}
 public record Comment(@Min(0) long expectedVersion,@NotBlank @Size(max=4000) String body,@NotNull @Pattern(regexp="PUBLIC_REPLY|INTERNAL_NOTE") String kind){}
 private final P3Base b;public ServiceDeskService(P3Base b){this.b=b;}
 static final String FROM=" FROM crm_ticket t JOIN sys_tenant_member m ON m.tenant_id=t.tenant_id AND m.id=t.owner_member_id JOIN sys_tenant_member am ON am.tenant_id=t.tenant_id AND am.id=t.assignee_member_id LEFT JOIN crm_customer c ON c.tenant_id=t.tenant_id AND c.id=t.customer_id JOIN crm_ticket_sla_episode e ON e.tenant_id=t.tenant_id AND e.ticket_id=t.id AND e.cycle_no=t.cycle_no ";
 private static String scope(boolean w){return "(:ticket"+(w?"WriteAll":"ReadAll")+" OR t.owner_member_id=:member OR t.assignee_member_id=:member OR (:ticket"+(w?"WriteDepartment":"ReadDepartment")+" AND (m.department_id=:department OR am.department_id=:department)))";}
 static final String READ="t.tenant_id=:tenant AND :ticketReader AND "+scope(false)+" AND(t.customer_id IS NULL OR (:customerReader AND "+CustomerService.READ+"))";
 private static final String SELECT="SELECT t.*,m.display_name AS owner_name,am.display_name AS assignee_name,c.customer_name,e.id AS episode_id,e.state AS sla_state,e.first_response_due_at,e.resolution_due_at,e.first_response_at,e.resolved_at,e.paused_at,e.response_breached_at,e.resolution_breached_at,(:ticketWriter AND "+scope(true)+") AS can_write"+FROM;
 static Instant time(Map<String,Object> row,String key){Object v=row.get(key);return v==null?null:v instanceof Instant t?t:Instant.parse(String.valueOf(v));}
 Map<String,Object> ticket(AuthService.Actor a,UUID id){var p=b.params(a);p.put("id",id);var r=b.one(SELECT+" WHERE "+READ+" AND t.id=:id",p);r.put("canManageSla",a.p3Access().slaManage());return r;}
 public Object get(AuthService.Session s,UUID id){return b.scoped(s,"ticket",false,a->ticket(a,id));}
 public Object list(AuthService.Session s,int page,int size,String q,String status,UUID customer,UUID assignee,String type){page(page,size,q);if(!type.matches("[A-Z0-9_]{0,40}"))throw ApiError.bad("工单类型无效");if(!Set.of("","NEW","IN_PROGRESS","WAITING_CUSTOMER","RESOLVED","CLOSED","CANCELLED").contains(status))throw ApiError.bad("工单状态无效");return b.scoped(s,"ticket",false,a->{var p=b.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"status",status,"customer",customer,"assignee",assignee,"type",type,"limit",size,"offset",((long)page-1)*size));String where=READ+" AND(:type='' OR t.type_code=:type) AND (:status='' OR t.status=:status) AND(cast(:customer AS uuid) IS NULL OR t.customer_id=:customer) AND(cast(:assignee AS uuid) IS NULL OR t.assignee_member_id=:assignee) AND(:q='' OR strpos(lower(t.title),:q)>0 OR strpos(lower(t.ticket_number),:q)>0 OR strpos(lower(coalesce(c.customer_name,'')),:q)>0)";return new BusinessService.Page<>(b.rows(SELECT+" WHERE "+where+" ORDER BY t.updated_at DESC,t.id LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*)"+FROM+" WHERE "+where,p,Long.class));});}
 public Object customerOptions(AuthService.Session s,int page,int size,String q){page(page,size,q);return b.scoped(s,"ticket",false,a->{if(!a.canReadCustomers())throw ApiError.forbidden("没有客户读取权限");var p=b.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"limit",size,"offset",((long)page-1)*size));String where="c.tenant_id=:tenant AND "+CustomerService.READ+" AND(:q='' OR strpos(lower(c.customer_name),:q)>0)";return new BusinessService.Page<>(b.rows("SELECT c.id,c.customer_name AS name FROM crm_customer c WHERE "+where+" ORDER BY c.customer_name,c.id LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*) FROM crm_customer c WHERE "+where,p,Long.class));});}
 public Object owners(AuthService.Session s){return b.scoped(s,"ticket",false,a->b.memberOptions(a,"ticket"));}
 private Map<String,Object> policy(AuthService.Actor a,UUID id){if(id==null)return map("name","内置自然时间 SLA","pauseWaiting",true,"escalate",true,"targets",List.of(new Target("URGENT",60,480),new Target("HIGH",240,1440),new Target("NORMAL",480,4320),new Target("LOW",1440,10080)));var r=b.one("SELECT * FROM crm_sla_policy WHERE tenant_id=:tenant AND id=:id AND active",map("tenant",a.tenant().id(),"id",id));try{var targets=b.data.json.convertValue(r.get("targets"),new com.fasterxml.jackson.core.type.TypeReference<List<Target>>(){});return map("name",r.get("name"),"pauseWaiting",r.get("pauseWaiting"),"escalate",r.get("escalate"),"targets",targets);}catch(Exception e){throw new IllegalStateException(e);}}
 @SuppressWarnings("unchecked") private Target target(Map<String,Object> policy,String priority){Object raw=policy.get("targets");if(raw instanceof List<?> rows){for(Object value:rows){if(value instanceof Target t&&t.priority().equals(priority))return t;if(value instanceof Map<?,?> v&&priority.equals(v.get("priority")))return new Target(priority,((Number)v.get("responseMinutes")).intValue(),((Number)v.get("resolutionMinutes")).intValue());}}throw ApiError.bad("SLA 优先级配置不完整");}
 public Object policies(AuthService.Session s){return b.scoped(s,"sla",false,a->{var list=b.rows("SELECT * FROM crm_sla_policy WHERE tenant_id=:tenant ORDER BY created_at,id",map("tenant",a.tenant().id()));return map("items",list,"builtin",policy(a,null),"calendar","CALENDAR_24X7");});}
 public Object savePolicy(AuthService.Session s,UUID id,SlaInput i,String key,UUID trace){return b.scoped(s,"sla",true,a->{var priorities=new HashSet<String>();for(var t:i.targets())if(!priorities.add(t.priority())||t.responseMinutes()>t.resolutionMinutes())throw ApiError.bad("四个优先级需唯一且响应时限不超过解决时限");UUID selected=id==null?b.once(a,"sla.create",key,i,()->{UUID created=UUID.randomUUID();b.db.update("INSERT INTO crm_sla_policy(id,tenant_id,name,targets,pause_waiting,escalate,active) VALUES(:id,:tenant,:name,cast(:targets AS jsonb),:pause,:escalate,:active)",map("id",created,"tenant",a.tenant().id(),"name",text(i.name()),"targets",b.json(i.targets()),"pause",i.pauseWaiting(),"escalate",i.escalate(),"active",i.active()));b.audit(a,"SLA_POLICY_CREATED","SLA_POLICY",created,0,trace);return created;}):id;if(id!=null){int n=b.db.update("UPDATE crm_sla_policy SET name=:name,targets=cast(:targets AS jsonb),pause_waiting=:pause,escalate=:escalate,active=:active,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",map("id",id,"tenant",a.tenant().id(),"version",i.expectedVersion(),"name",text(i.name()),"targets",b.json(i.targets()),"pause",i.pauseWaiting(),"escalate",i.escalate(),"active",i.active()));if(n!=1)throw ApiError.conflict("SLA 策略已变化");b.audit(a,"SLA_POLICY_UPDATED","SLA_POLICY",id,i.expectedVersion()+1,trace);}return b.one("SELECT * FROM crm_sla_policy WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",selected));});}
 void assignee(AuthService.Actor a,UUID member,UUID customer){if(b.memberOptions(a,"ticket").stream().noneMatch(m->member.equals(m.get("id"))))throw ApiError.bad("负责人不在当前可分配范围或尚未完成登录准备");var candidate=b.actor(a.tenant().id(),member);if("OFF_DUTY".equals(b.one("SELECT service_status FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",member)).get("serviceStatus")))throw ApiError.conflict("该人员当前不接单，请选择在岗人员");b.customer(candidate,customer,false);}
 private void episode(UUID tenant,UUID ticket,int cycle,Map<String,Object> policy,String priority,Instant anchor){var t=target(policy,priority);b.db.update("INSERT INTO crm_ticket_sla_episode(id,tenant_id,ticket_id,cycle_no,first_response_due_at,resolution_due_at,state) VALUES(:id,:tenant,:ticket,:cycle,:response,:resolution,'ACTIVE')",map("id",UUID.randomUUID(),"tenant",tenant,"ticket",ticket,"cycle",cycle,"response",anchor.plusSeconds(t.responseMinutes()*60L),"resolution",anchor.plusSeconds(t.resolutionMinutes()*60L)));}
 public Object create(AuthService.Session s,TicketInput i,String key,UUID trace){return b.scoped(s,"ticket",true,a->{UUID id=b.once(a,"ticket.create",key,i,()->{b.customer(a,i.customerId(),false);assignee(a,i.assigneeMemberId(),i.customerId());var policy=policy(a,i.slaPolicyId());String type=i.typeCode()==null?"GENERAL":i.typeCode();if(b.db.queryForObject("SELECT count(*) FROM crm_dictionary_item WHERE tenant_id=:tenant AND dictionary_type='TICKET_TYPE' AND item_code=:code AND active",map("tenant",a.tenant().id(),"code",type),Integer.class)!=1)throw ApiError.bad("工单类型无效");UUID created=UUID.randomUUID();var p=map("tenant",a.tenant().id(),"year",today().getYear());long seq=b.db.queryForObject("INSERT INTO crm_ticket_counter(tenant_id,ticket_year,next_value) VALUES(:tenant,:year,1) ON CONFLICT(tenant_id,ticket_year) DO UPDATE SET next_value=crm_ticket_counter.next_value+1 RETURNING next_value",p,Long.class);b.db.update("INSERT INTO crm_ticket(id,tenant_id,ticket_number,title,description,customer_id,owner_member_id,assignee_member_id,requester_name,requester_email,priority,sla_policy_id,sla_snapshot,type_code) VALUES(:id,:tenant,:number,:title,:body,:customer,:member,:assignee,:name,:email,:priority,:policy,cast(:snapshot AS jsonb),:type)",map("id",created,"tenant",a.tenant().id(),"number",P4Numbering.format(b.db,a.tenant().id(),"TICKET",today().getYear(),seq,"CS"),"title",text(i.title()),"body",text(i.description()),"customer",i.customerId(),"member",a.tenant().memberId(),"assignee",i.assigneeMemberId(),"name",text(i.requesterName()),"email",text(i.requesterEmail()),"priority",i.priority(),"policy",i.slaPolicyId(),"snapshot",b.json(policy),"type",type));episode(a.tenant().id(),created,1,policy,i.priority(),Instant.now());revision(a,created,"CREATED","",trace);notice(a,created,i.assigneeMemberId(),"ASSIGNED","assigned:0");return created;});return ticket(a,id);});}
 public Object edit(AuthService.Session s,UUID id,TicketInput i,UUID trace){return b.scoped(s,"ticket",true,a->{var old=ticket(a,id);if(!Boolean.TRUE.equals(old.get("canWrite"))||!"NEW".equals(old.get("status")))throw ApiError.forbidden("仅获准的新工单可编辑基础资料");b.version(old,i.expectedVersion());breaches(a.tenant().id(),id);if(!Objects.equals(old.get("customerId"),i.customerId()))throw ApiError.bad("已有工单不能换客户");assignee(a,i.assigneeMemberId(),i.customerId());String type=i.typeCode()==null?String.valueOf(old.get("typeCode")):i.typeCode();if(b.db.queryForObject("SELECT count(*) FROM crm_dictionary_item WHERE tenant_id=:tenant AND dictionary_type='TICKET_TYPE' AND item_code=:code AND active",map("tenant",a.tenant().id(),"code",type),Integer.class)!=1)throw ApiError.bad("工单类型无效");boolean slaChanged=!old.get("priority").equals(i.priority())||!Objects.equals(old.get("slaPolicyId"),i.slaPolicyId());if(slaChanged&&!a.p3Access().slaManage())throw ApiError.forbidden("调整已有 SLA 需经理权限");var policy=slaChanged?policy(a,i.slaPolicyId()):(Map<String,Object>)old.get("slaSnapshot");b.db.update("UPDATE crm_ticket SET title=:title,description=:body,assignee_member_id=:assignee,assigned_at=CASE WHEN assignee_member_id<>:assignee THEN now() ELSE assigned_at END,accepted_at=CASE WHEN assignee_member_id<>:assignee THEN NULL ELSE accepted_at END,requester_name=:name,requester_email=:email,priority=:priority,sla_policy_id=:policy,sla_snapshot=cast(:snapshot AS jsonb),type_code=:type,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",map("tenant",a.tenant().id(),"id",id,"title",text(i.title()),"body",text(i.description()),"assignee",i.assigneeMemberId(),"name",text(i.requesterName()),"email",text(i.requesterEmail()),"priority",i.priority(),"policy",i.slaPolicyId(),"snapshot",b.json(policy),"type",type,"version",i.expectedVersion()));if(slaChanged){var t=target(policy,i.priority());Instant anchor=time(old,"createdAt");b.db.update("UPDATE crm_ticket_sla_episode SET first_response_due_at=:response,resolution_due_at=:resolution WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",old.get("episodeId"),"response",anchor.plusSeconds(t.responseMinutes()*60L),"resolution",anchor.plusSeconds(t.resolutionMinutes()*60L)));}revision(a,id,"UPDATED","",trace);if(!i.assigneeMemberId().equals(old.get("assigneeMemberId")))notice(a,id,i.assigneeMemberId(),"ASSIGNED","assigned:"+(i.expectedVersion()+1));return ticket(a,id);});}
 public Object action(AuthService.Session s,UUID id,String action,Change i,String key,UUID trace){return b.scoped(s,"ticket",true,a->{UUID result=b.once(a,"ticket."+action,key,map("id",id,"input",i),()->{var t=ticket(a,id);if(!Boolean.TRUE.equals(t.get("canWrite")))throw ApiError.forbidden("无权处理该工单");b.version(t,i.expectedVersion());breaches(a.tenant().id(),id);String state=(String)t.get("status"),next;Instant now=Instant.now();var p=map("tenant",a.tenant().id(),"id",id,"episode",t.get("episodeId"),"now",now);boolean pause=Boolean.TRUE.equals(((Map<?,?>)t.get("slaSnapshot")).get("pauseWaiting"));switch(action){
 case "start"->{if(!state.equals("NEW"))throw ApiError.conflict("仅新工单可接单处理");if(!a.tenant().memberId().equals(t.get("assigneeMemberId")))throw ApiError.forbidden("只有被派工人员可接单");b.db.update("UPDATE crm_ticket SET accepted_at=now() WHERE tenant_id=:tenant AND id=:id",p);next="IN_PROGRESS";}
 case "wait"->{if(!state.equals("IN_PROGRESS")||t.get("firstResponseAt")==null)throw ApiError.conflict("先公开回复，再登记等待客户");next="WAITING_CUSTOMER";if(pause)b.db.update("UPDATE crm_ticket_sla_episode SET state='PAUSED',paused_at=:now,response_remaining_ms=CASE WHEN first_response_at IS NULL THEN (extract(epoch FROM(first_response_due_at-:now))*1000)::bigint ELSE NULL END,resolution_remaining_ms=(extract(epoch FROM(resolution_due_at-:now))*1000)::bigint WHERE tenant_id=:tenant AND id=:episode",p);}
 case "resume"->{if(!state.equals("WAITING_CUSTOMER"))throw ApiError.conflict("仅等待客户工单可恢复");next="IN_PROGRESS";if(pause)b.db.update("UPDATE crm_ticket_sla_episode SET state='ACTIVE',paused_total_ms=paused_total_ms+greatest((extract(epoch FROM(cast(:now AS timestamptz)-paused_at))*1000)::bigint,0),first_response_due_at=CASE WHEN first_response_at IS NULL THEN cast(:now AS timestamptz)+response_remaining_ms*interval '1 millisecond' ELSE first_response_due_at END,resolution_due_at=cast(:now AS timestamptz)+resolution_remaining_ms*interval '1 millisecond',paused_at=NULL,response_remaining_ms=NULL,resolution_remaining_ms=NULL WHERE tenant_id=:tenant AND id=:episode",p);}
 case "resolve"->{if(!state.equals("IN_PROGRESS"))throw ApiError.conflict("仅处理中的工单可解决");if(t.get("firstResponseAt")==null)throw ApiError.conflict("先公开回复，再登记解决");next="RESOLVED";b.db.update("UPDATE crm_ticket_sla_episode SET state='RESOLVED',resolved_at=:now WHERE tenant_id=:tenant AND id=:episode",p);}
 case "close"->{if(!state.equals("RESOLVED"))throw ApiError.conflict("先解决，再关闭");next="CLOSED";}
 case "reopen"->{if(!Set.of("RESOLVED","CLOSED").contains(state))throw ApiError.conflict("仅已解决 / 已关闭工单可重开");next="IN_PROGRESS";int cycle=((Number)t.get("cycleNo")).intValue()+1;if(cycle>1000)throw ApiError.conflict("重开次数达到上限");b.db.update("UPDATE crm_ticket SET cycle_no=:cycle WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"cycle",cycle));episode(a.tenant().id(),id,cycle,(Map<String,Object>)t.get("slaSnapshot"),(String)t.get("priority"),now);}
 case "cancel"->{if(!state.equals("NEW"))throw ApiError.conflict("仅新工单可取消");next="CANCELLED";b.db.update("UPDATE crm_ticket_sla_episode SET state='CANCELLED' WHERE tenant_id=:tenant AND id=:episode",p);}
 default->throw ApiError.bad("工单动作无效");}
 String reason=text(i.reason());if(reason.isEmpty())throw ApiError.bad("请填写处理原因或解决说明");b.db.update("UPDATE crm_ticket SET status=:status,resolution=CASE WHEN :status='RESOLVED' THEN :reason ELSE resolution END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"status",next,"reason",reason));revision(a,id,action.toUpperCase(Locale.ROOT),reason,trace);return id;});return ticket(a,result);});}
 public Object comment(AuthService.Session s,UUID id,Comment i,String key,UUID trace){return b.scoped(s,"ticket",true,a->{UUID result=b.once(a,"ticket.comment",key,map("id",id,"input",i),()->{var t=ticket(a,id);if(!Boolean.TRUE.equals(t.get("canWrite"))||!Set.of("NEW","IN_PROGRESS","WAITING_CUSTOMER").contains(t.get("status")))throw ApiError.forbidden("当前工单不能追加处理记录");b.version(t,i.expectedVersion());breaches(a.tenant().id(),id);UUID created=UUID.randomUUID();b.db.update("INSERT INTO crm_ticket_comment(id,tenant_id,ticket_id,body,kind,actor_member_id,actor_name_snapshot) VALUES(:id,:tenant,:ticket,:body,:kind,:member,:name)",map("id",created,"tenant",a.tenant().id(),"ticket",id,"body",text(i.body()),"kind",i.kind(),"member",a.tenant().memberId(),"name",a.tenant().memberName()));if(i.kind().equals("PUBLIC_REPLY"))b.db.update("UPDATE crm_ticket_sla_episode SET first_response_work_ms=CASE WHEN first_response_at IS NULL THEN greatest((extract(epoch FROM(now()-created_at))*1000)::bigint-paused_total_ms-CASE WHEN paused_at IS NOT NULL THEN (extract(epoch FROM(now()-paused_at))*1000)::bigint ELSE 0 END,0) ELSE first_response_work_ms END,first_response_at=coalesce(first_response_at,now()) WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",t.get("episodeId")));b.db.update("UPDATE crm_ticket SET version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));revision(a,id,"COMMENTED",i.kind(),trace);return id;});return ticket(a,result);});}
 void revision(AuthService.Actor a,UUID id,String action,String reason,UUID trace){var t=ticket(a,id);t.remove("canWrite");t.remove("canManageSla");b.db.update("INSERT INTO crm_ticket_revision(id,tenant_id,ticket_id,business_version,action,snapshot,reason,actor_member_id,actor_name_snapshot) VALUES(:revision,:tenant,:ticket,:version,:action,cast(:snapshot AS jsonb),:reason,:member,:name)",map("revision",UUID.randomUUID(),"tenant",a.tenant().id(),"ticket",id,"version",t.get("version"),"action",action,"snapshot",b.json(t),"reason",reason,"member",a.tenant().memberId(),"name",a.tenant().memberName()));b.audit(a,"TICKET_"+action,"TICKET",id,number(t,"version"),trace);}
 public Object history(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return b.scoped(s,"ticket",false,a->{ticket(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(b.rows("SELECT id,business_version,action,reason,actor_name_snapshot,created_at FROM crm_ticket_revision WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY business_version DESC LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*) FROM crm_ticket_revision WHERE tenant_id=:tenant AND ticket_id=:id",p,Long.class));});}
 public Object revision(AuthService.Session s,UUID id,long version){if(version<0)throw ApiError.bad("版本无效");return b.scoped(s,"ticket",false,a->{ticket(a,id);return b.object(String.valueOf(b.one("SELECT snapshot::text AS value FROM crm_ticket_revision WHERE tenant_id=:tenant AND ticket_id=:id AND business_version=:version",map("tenant",a.tenant().id(),"id",id,"version",version)).get("value")));});}
 public Object comments(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return b.scoped(s,"ticket",false,a->{ticket(a,id);var p=map("tenant",a.tenant().id(),"id",id,"limit",size,"offset",((long)page-1)*size);return new BusinessService.Page<>(b.rows("SELECT * FROM crm_ticket_comment WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY created_at DESC,id LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*) FROM crm_ticket_comment WHERE tenant_id=:tenant AND ticket_id=:id",p,Long.class));});}
 public Object episodes(AuthService.Session s,UUID id){return b.scoped(s,"ticket",false,a->{ticket(a,id);return map("episodes",b.rows("SELECT * FROM crm_ticket_sla_episode WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY cycle_no",map("tenant",a.tenant().id(),"id",id)),"breaches",b.rows("SELECT * FROM crm_sla_breach WHERE tenant_id=:tenant AND ticket_id=:id ORDER BY detected_at,id",map("tenant",a.tenant().id(),"id",id)));});}
 private void notice(AuthService.Actor a,UUID ticket,UUID member,String topic,String event){b.db.update("INSERT INTO crm_service_notification(id,tenant_id,ticket_id,member_id,topic,event_key) VALUES(:id,:tenant,:ticket,:member,:topic,:event) ON CONFLICT DO NOTHING",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"ticket",ticket,"member",member,"topic",topic,"event",ticket+":"+event));}
 int breaches(UUID tenant){return breaches(tenant,null);}
 private int breaches(UUID tenant,UUID selected){b.context(tenant);var due=b.rows("SELECT e.*,t.assignee_member_id,t.owner_member_id,t.sla_snapshot,ticket_number FROM crm_ticket_sla_episode e JOIN crm_ticket t ON t.tenant_id=e.tenant_id AND t.id=e.ticket_id AND t.cycle_no=e.cycle_no WHERE e.tenant_id=:tenant AND (cast(:selected AS uuid) IS NULL OR t.id=:selected) AND e.state='ACTIVE' AND ((e.first_response_at IS NULL AND e.first_response_due_at<now() AND e.response_breached_at IS NULL) OR(e.resolution_due_at<now() AND e.resolution_breached_at IS NULL)) ORDER BY e.id LIMIT 500",map("tenant",tenant,"selected",selected));int count=0;for(var e:due){for(String kind:List.of("RESPONSE","RESOLUTION")){String column=kind.equals("RESPONSE")?"firstResponseDueAt":"resolutionDueAt",breached=kind.equals("RESPONSE")?"responseBreachedAt":"resolutionBreachedAt";if(e.get(column)==null||!time(e,column).isBefore(Instant.now())||e.get(breached)!=null||kind.equals("RESPONSE")&&e.get("firstResponseAt")!=null)continue;UUID id=UUID.randomUUID();int changed=b.db.update("INSERT INTO crm_sla_breach(id,tenant_id,ticket_id,episode_id,kind,due_at) VALUES(:id,:tenant,:ticket,:episode,:kind,:due) ON CONFLICT DO NOTHING",map("id",id,"tenant",tenant,"ticket",e.get("ticketId"),"episode",e.get("id"),"kind",kind,"due",e.get(column)));b.db.update("UPDATE crm_ticket_sla_episode SET "+(kind.equals("RESPONSE")?"response_breached_at":"resolution_breached_at")+"=coalesce("+(kind.equals("RESPONSE")?"response_breached_at":"resolution_breached_at")+",now()) WHERE tenant_id=:tenant AND id=:id",map("tenant",tenant,"id",e.get("id")));if(changed==0)continue;count++;var recipients=new HashSet<UUID>();recipients.add((UUID)e.get("assigneeMemberId"));recipients.add((UUID)e.get("ownerMemberId"));if(Boolean.TRUE.equals(((Map<?,?>)e.get("slaSnapshot")).get("escalate")))recipients.addAll(b.db.queryForList("SELECT m.id FROM sys_tenant_member m JOIN sys_member_role r ON r.tenant_id=m.tenant_id AND r.member_id=m.id WHERE m.tenant_id=:tenant AND r.role_code='SALES_MANAGER' AND m.status='ACTIVE'",map("tenant",tenant),UUID.class));for(UUID member:recipients)try{var a=b.actor(tenant,member);if(!a.p3Access().tickets().read())continue;ticket(a,(UUID)e.get("ticketId"));notice(a,(UUID)e.get("ticketId"),member,"SLA_"+kind,"breach:"+id);}catch(ApiError ignored){}}}return count;}
 public Object run(AuthService.Session s){return b.scoped(s,"sla",true,a->map("processed",breaches(a.tenant().id())));}
 public Object notifications(AuthService.Session s){return b.scoped(s,"ticket",false,a->{var ns=b.rows("SELECT * FROM crm_service_notification WHERE tenant_id=:tenant AND member_id=:member ORDER BY created_at DESC,id LIMIT 200",map("tenant",a.tenant().id(),"member",a.tenant().memberId()));var result=new ArrayList<Map<String,Object>>();for(var n:ns)try{var t=ticket(a,(UUID)n.get("ticketId"));n.put("title",t.get("title"));n.put("ticketNumber",t.get("ticketNumber"));result.add(n);}catch(ApiError ignored){}return map("items",result,"unread",result.stream().filter(n->n.get("readAt")==null).count());});}
 public Object readNotice(AuthService.Session s,UUID id){return b.scoped(s,"ticket",false,a->{var n=b.one("SELECT * FROM crm_service_notification WHERE tenant_id=:tenant AND member_id=:member AND id=:id",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));ticket(a,(UUID)n.get("ticketId"));b.db.update("UPDATE crm_service_notification SET read_at=coalesce(read_at,now()) WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));return null;});}
 public Object report(AuthService.Session s,LocalDate from,LocalDate to){date(from);date(to);if(to.isBefore(from)||to.isAfter(today())||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366)throw ApiError.bad("报表日期最多367天且不晚于今天");return b.scoped(s,"ticket",false,a->{var p=b.params(a);p.putAll(map("from",from.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant(),"to",to.plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant()));var summary=b.one("SELECT count(*) AS tickets,count(*) FILTER(WHERE t.status IN('NEW','IN_PROGRESS','WAITING_CUSTOMER')) AS open,count(*) FILTER(WHERE t.status IN('RESOLVED','CLOSED')) AS resolved,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM crm_sla_breach z WHERE z.tenant_id=t.tenant_id AND z.ticket_id=t.id)) AS breached,round(avg(extract(epoch FROM(e.first_response_at-e.created_at))/60),2) AS response_minutes"+FROM+" WHERE "+READ+" AND t.created_at>=:from AND t.created_at<:to",p);var owners=b.rows("SELECT am.display_name AS name,count(*) AS tickets,count(*) FILTER(WHERE t.status IN('NEW','IN_PROGRESS','WAITING_CUSTOMER')) AS open"+FROM+" WHERE "+READ+" AND t.created_at>=:from AND t.created_at<:to GROUP BY am.id,am.display_name ORDER BY am.display_name",p);return map("summary",summary,"owners",owners,"from",from,"to",to,"calendar","自然时间 24x7");});}
 public byte[] export(AuthService.Session s,String q,String state,UUID customer,UUID assignee,UUID trace){page(1,100,q);return b.scoped(s,"export-ticket",false,a->{var p=b.params(a);p.putAll(map("q",text(q).toLowerCase(Locale.ROOT),"state",state,"customer",customer,"assignee",assignee));var rs=b.rows(SELECT+" WHERE "+READ+" AND(:q='' OR strpos(lower(t.title),:q)>0 OR strpos(lower(t.ticket_number),:q)>0 OR strpos(lower(coalesce(c.customer_name,'')),:q)>0) AND(cast(:customer AS uuid) IS NULL OR t.customer_id=:customer) AND(cast(:assignee AS uuid) IS NULL OR t.assignee_member_id=:assignee) AND(:state='' OR t.status=:state) ORDER BY t.ticket_number LIMIT 5001",p);if(rs.size()>5000)throw ApiError.bad("导出最多5000条，请缩小条件");b.audit(a,"TICKETS_EXPORTED","TICKET_EXPORT",a.tenant().id(),0,trace);return CsvSupport.write(List.of("工单编号","主题","客户","状态","优先级","负责人","SLA响应截止","SLA解决截止"),rs.stream().map(r->Arrays.<Object>asList(r.get("ticketNumber"),r.get("title"),r.get("customerName"),r.get("status"),r.get("priority"),r.get("assigneeName"),r.get("firstResponseDueAt"),r.get("resolutionDueAt"))).toList());});}
}
